ALTER TABLE public.customers ADD COLUMN credit_limit numeric DEFAULT NULL, ADD COLUMN payment_terms_days integer NOT NULL DEFAULT 14;
ALTER TABLE public.customers ADD CONSTRAINT customers_credit_nonnegative CHECK (credit_limit IS NULL OR credit_limit >= 0), ADD CONSTRAINT customers_terms_range CHECK (payment_terms_days BETWEEN 0 AND 365);
CREATE TABLE public.customer_payment_reminders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES public.sales_records(id), customer_id uuid NOT NULL REFERENCES public.customers(id), reminder_date date NOT NULL DEFAULT CURRENT_DATE, status text NOT NULL DEFAULT 'sending', sent_by uuid NOT NULL, sent_at timestamptz, UNIQUE(sale_id, reminder_date));
GRANT SELECT ON public.customer_payment_reminders TO authenticated;
GRANT ALL ON public.customer_payment_reminders TO service_role;
ALTER TABLE public.customer_payment_reminders ENABLE ROW LEVEL SECURITY;
CREATE POLICY reminder_admin_read ON public.customer_payment_reminders FOR SELECT TO authenticated USING (public.is_admin());
CREATE OR REPLACE FUNCTION public.enforce_customer_credit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lim numeric; balance numeric; BEGIN IF NEW.customer_id IS NULL THEN RETURN NEW; END IF; PERFORM 1 FROM public.customers WHERE id=NEW.customer_id FOR UPDATE; SELECT credit_limit INTO lim FROM public.customers WHERE id=NEW.customer_id; IF lim IS NULL THEN RETURN NEW; END IF; SELECT COALESCE(SUM(GREATEST(total_amount-CASE WHEN payment_status='paid' THEN total_amount ELSE COALESCE(amount_paid,0) END,0)),0) INTO balance FROM public.sales_records WHERE customer_id=NEW.customer_id AND id<>NEW.id; IF GREATEST(NEW.total_amount-CASE WHEN NEW.payment_status='paid' THEN NEW.total_amount ELSE COALESCE(NEW.amount_paid,0) END,0)>0 AND balance+GREATEST(NEW.total_amount-COALESCE(NEW.amount_paid,0),0)>lim THEN RAISE EXCEPTION 'Customer credit limit exceeded. Record payment or increase their credit limit before adding more unpaid goods.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_customer_credit BEFORE INSERT OR UPDATE OF customer_id,total_amount,amount_paid,payment_status ON public.sales_records FOR EACH ROW EXECUTE FUNCTION public.enforce_customer_credit();
CREATE TABLE public.batch_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.livestock_batches(id), title text NOT NULL, category text NOT NULL DEFAULT 'Other', file_path text NOT NULL UNIQUE, file_name text NOT NULL, file_size integer NOT NULL, uploaded_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.batch_documents TO authenticated;
GRANT ALL ON public.batch_documents TO service_role;
ALTER TABLE public.batch_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.batch_documents FOR SELECT TO authenticated USING (public.is_admin() OR public.partner_has_batch(batch_id));
CREATE POLICY documents_insert ON public.batch_documents FOR INSERT TO authenticated WITH CHECK ((public.is_admin() OR public.partner_has_batch(batch_id)) AND uploaded_by=auth.uid() AND split_part(file_path,'/',1)=batch_id::text);
CREATE POLICY documents_delete ON public.batch_documents FOR DELETE TO authenticated USING (public.is_admin());
CREATE POLICY batch_documents_storage_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='batch-documents' AND EXISTS(SELECT 1 FROM public.livestock_batches b WHERE b.id::text=split_part(name,'/',1) AND (public.is_admin() OR public.partner_has_batch(b.id))));
CREATE POLICY batch_documents_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='batch-documents' AND EXISTS(SELECT 1 FROM public.livestock_batches b WHERE b.id::text=split_part(name,'/',1) AND (public.is_admin() OR public.partner_has_batch(b.id))));
CREATE POLICY batch_documents_storage_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='batch-documents' AND public.is_admin());
CREATE TABLE public.batch_water_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.livestock_batches(id), date date NOT NULL, litres numeric NOT NULL CHECK(litres>0), birds_at_record integer NOT NULL CHECK(birds_at_record>0), temperature_c numeric CHECK(temperature_c BETWEEN -10 AND 60), notes text, recorded_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(batch_id,date));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.batch_water_records TO authenticated;
GRANT ALL ON public.batch_water_records TO service_role;
ALTER TABLE public.batch_water_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY water_read ON public.batch_water_records FOR SELECT TO authenticated USING (public.is_admin() OR public.partner_has_batch(batch_id));
CREATE POLICY water_insert ON public.batch_water_records FOR INSERT TO authenticated WITH CHECK ((public.is_admin() OR public.partner_has_batch(batch_id)) AND recorded_by=auth.uid());
CREATE POLICY water_update ON public.batch_water_records FOR UPDATE TO authenticated USING (public.is_admin() OR public.partner_has_batch(batch_id)) WITH CHECK (public.is_admin() OR public.partner_has_batch(batch_id));
CREATE POLICY water_delete ON public.batch_water_records FOR DELETE TO authenticated USING (public.is_admin());
CREATE OR REPLACE FUNCTION public.get_batch_trace(_batch_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT (public.is_admin() OR public.partner_has_batch(_batch_id)) THEN RAISE EXCEPTION 'This batch is only accessible to an administrator or its assigned partner'; END IF; SELECT jsonb_build_object('id',b.id,'species',b.species,'species_type',b.species_type,'source',b.source,'date_acquired',b.date_acquired,'age_weeks',b.age_weeks,'quantity',b.quantity,'current_quantity',b.current_quantity,'is_active',b.is_active,'branch',br.name,'mortality',COALESCE((SELECT SUM(quantity_dead) FROM public.mortality_records WHERE batch_id=b.id),0),'egg_pieces',COALESCE((SELECT SUM(crates*30+pieces) FROM public.batch_egg_production WHERE batch_id=b.id),0),'care',(SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (SELECT care_date,care_type,description FROM public.livestock_care_logs WHERE batch_id=b.id ORDER BY care_date DESC LIMIT 15) x)) INTO result FROM public.livestock_batches b LEFT JOIN public.branches br ON br.id=b.branch_id WHERE b.id=_batch_id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.get_batch_trace(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_batch_trace(uuid) TO authenticated, service_role;